+const { PaymentBatch, PayrollLine, Staff } = require('../models');
+const hrmsAdapter = require('../adapters/hrmsAdapter');
+const { recordAudit } = require('./auditService');
+
+function buildHrmsPayload({ batch, lines }) {
+  return {
+    paymentBatchId: batch.id,
+    payPeriodId: batch.payPeriodId,
+    lines: lines.map((line) => {
+      const staff = line.Staff || {};
+      return {
+        staffExternalRef: staff.externalRef,
+        staffName: staff.fullName,
+        grossPay: Number(line.grossPay || 0),
+        incentivePay: Number(line.incentivePay || 0),
+        cpfAmount: Number(line.cpfAmount || 0),
+        sdlAmount: Number(line.sdlAmount || 0),
+        netPay: Number(line.netPay || 0)
+      };
+    })
+  };
+}
+
+async function syncBatchToHrms(batchId, actor = 'Accounting Staff') {
+  const batch = await PaymentBatch.findByPk(batchId);
+  if (!batch) {
+    const error = new Error('Payment batch not found');
+    error.status = 404;
+    error.code = 'PAYMENT_BATCH_NOT_FOUND';
+    throw error;
+  }
+
+  const lines = await PayrollLine.findAll({
+    where: { payPeriodId: batch.payPeriodId, status: 'ok' },
+    include: [{ model: Staff }]
+  });
+
