+  batch.status = 'hrms_sync_pending';
+  batch.hrmsPayload = payload;
+  await batch.save();
+
+  try {
+    const result = await hrmsAdapter.pushPayrollFigures(payload);
+    batch.status = 'completed';
+    batch.hrmsReference = result.reference;
+    batch.hrmsError = null;
+    await batch.save();
+
