+      entityType: 'payment_batch',
+      entityId: batch.id,
+      action: 'hrms_synced',
+      actor,
+      detail: result
+    });
+
+    return { batch, result };
+  } catch (err) {
+    batch.status = 'hrms_sync_failed';
+    batch.hrmsError = err.message;
+    await batch.save();
+
+    await recordAudit({
+      entityType: 'payment_batch',
+      entityId: batch.id,
+      action: 'hrms_sync_failed',
+      actor,
+      detail: { message: err.message }
+    });
+
+    const error = new Error('Payment file retained; retry HRMS sync');
+    error.status = 502;
+    error.code = 'HRMS_SYNC_INCOMPLETE';
+    error.batch = batch;
+    throw error;
+  }
+}
+
+module.exports = {
+  buildHrmsPayload,
+  syncBatchToHrms
+};
