+const { PayPeriod, PayrollLine, Staff, PaymentBatch } = require('../models');
+const bankingAdapter = require('../adapters/bankingAdapter');
+const { formatGiroFile } = require('../utils/giroFileFormatter');
+const { generatePayslips } = require('./payslipService');
+const { syncBatchToHrms } = require('./hrmsSyncService');
+const { recordAudit } = require('./auditService');
+
+function ensureApprovedPeriod(payPeriod) {
+  if (!payPeriod) {
+    const error = new Error('Pay period not found');
+    error.status = 404;
+    error.code = 'PAY_PERIOD_NOT_FOUND';
+    throw error;
+  }
+
+  if (payPeriod.status !== 'approved' || !payPeriod.isLocked) {
+    const error = new Error('Payroll must be approved and locked before payment file generation');
+    error.status = 409;
+    error.code = 'PERIOD_NOT_APPROVED';
+    throw error;
+  }
+}
+
+function findMissingBankDetails(lines) {
+  return lines
+    .filter((line) => {
+      const staff = line.Staff || {};
+      return !staff.bankAccountNo || !staff.bankCode;
+    })
+    .map((line) => ({
+      staffId: line.staffId,
+      fullName: line.Staff ? line.Staff.fullName : 'Unknown staff'
+    }));
+}
+
+async function getPayableLines(payPeriodId) {
+  return PayrollLine.findAll({
+    where: { payPeriodId, status: 'ok' },
+    include: [{ model: Staff }],
+    order: [['id', 'ASC']]
+  });
+}
+
+async function generatePaymentFile({ payPeriodId, actor = 'Accounting Staff' }) {
+  const payPeriod = await PayPeriod.findByPk(payPeriodId);
+  ensureApprovedPeriod(payPeriod);
+
+  const lines = await getPayableLines(payPeriodId);
+  if (lines.length === 0) {
+    const error = new Error('No payable payroll lines found for this period');
+    error.status = 409;
+    error.code = 'NO_PAYROLL_LINES';
+    throw error;
+  }
+
+  const affectedStaff = findMissingBankDetails(lines);
+  if (affectedStaff.length > 0) {
+    const error = new Error('File not generated; staff missing bank details');
+    error.status = 424;
+    error.code = 'MISSING_BANK_DETAILS';
+    error.affectedStaff = affectedStaff;
+    throw error;
+  }
+
+  const generatedAt = new Date();
+  const fileName = `giro-pay-period-${payPeriodId}-${generatedAt.toISOString().slice(0, 10)}.txt`;
+  const fileContent = formatGiroFile({ payPeriod, lines, generatedAt });
+  const storedFile = await bankingAdapter.storePaymentFile({ fileName, content: fileContent });
+  const payslips = await generatePayslips(lines);
+
+  const batch = await PaymentBatch.create({
+    payPeriodId,
+    fileFormat: 'giro',
+    fileName,
+    filePath: storedFile.filePath,
+    fileContent,
+    status: 'generated',
+    payslipCount: payslips.length,
+    generatedAt
+  });
+
+  await recordAudit({
+    entityType: 'payment_batch',
+    entityId: batch.id,
+    action: 'payment_file_generated',
+    actor,
+    detail: {
+      fileName,
+      lineCount: lines.length,
+      totalNet: lines.reduce((sum, line) => sum + Number(line.netPay || 0), 0)
+    }
+  });
+
+  let hrmsSync = 'completed';
+  try {
+    await syncBatchToHrms(batch.id, actor);
+  } catch (err) {
+    if (err.code !== 'HRMS_SYNC_INCOMPLETE') {
+      throw err;
+    }
+    hrmsSync = 'failed';
+  }
+
+  const refreshedBatch = await PaymentBatch.findByPk(batch.id);
+  if (hrmsSync === 'completed') {
+    payPeriod.status = 'payment_ready';
+    await payPeriod.save();
+  }
+
+  return {
+    payPeriod,
+    batch: refreshedBatch,
+    payslips,
+    hrmsSync
+  };
+}
+
+async function getBatchFile(batchId) {
+  const batch = await PaymentBatch.findByPk(batchId);
+  if (!batch || !batch.fileContent) {
+    const error = new Error('Payment file not found');
+    error.status = 404;
+    error.code = 'PAYMENT_FILE_NOT_FOUND';
+    throw error;
+  }
+
+  return batch;
+}
+
+module.exports = {
+  ensureApprovedPeriod,
+  findMissingBankDetails,
+  generatePaymentFile,
+  getBatchFile
+};
