+const yup = require('yup');
+const { PaymentBatch } = require('../models');
+const paymentFileService = require('../services/paymentFileService');
+const { syncBatchToHrms } = require('../services/hrmsSyncService');
+
+const generateSchema = yup.object({
+  payPeriodId: yup.number().integer().positive().required(),
+  actor: yup.string().trim().max(120).default('Accounting Staff')
+});
+
+function sendError(res, err) {
+  const status = err.status || 500;
+  const body = {
+    error: err.code || 'PAYMENT_ERROR',
+    message: err.message
+  };
+
+  if (err.affectedStaff) {
+    body.affectedStaff = err.affectedStaff;
+  }
+
+  if (err.batch) {
+    body.paymentBatchId = err.batch.id;
+  }
+
+  return res.status(status).json(body);
+}
+
+async function generatePayment(req, res) {
+  try {
+    const data = await generateSchema.validate(req.body, { abortEarly: false });
+    const result = await paymentFileService.generatePaymentFile(data);
+    const batch = result.batch;
+
+    res.json({
+      payPeriodId: result.payPeriod.id,
+      status: result.payPeriod.status,
+      paymentBatchId: batch.id,
+      fileFormat: batch.fileFormat,
+      fileUrl: `/api/payments/${batch.id}/file`,
+      hrmsSync: result.hrmsSync,
+      batchStatus: batch.status,
+      payslipsGenerated: result.payslips.length
+    });
+  } catch (err) {
+    if (err.name === 'ValidationError') {
+      return res.status(400).json({ error: 'VALIDATION_ERROR', errors: err.errors });
+    }
+    return sendError(res, err);
+  }
+}
+
+async function downloadFile(req, res) {
+  try {
+    const batch = await paymentFileService.getBatchFile(req.params.batchId);
+    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
+    res.setHeader('Content-Disposition', `attachment; filename="${batch.fileName}"`);
+    res.send(batch.fileContent);
+  } catch (err) {
+    sendError(res, err);
+  }
+}
+
+async function retryHrms(req, res) {
+  try {
+    const actor = req.body.actor || 'Accounting Staff';
+    const { batch, result } = await syncBatchToHrms(req.params.batchId, actor);
+    res.json({
+      paymentBatchId: batch.id,
+      hrmsSync: 'completed',
+      batchStatus: batch.status,
+      hrmsReference: result.reference
+    });
+  } catch (err) {
+    sendError(res, err);
+  }
+}
+
+async function getBatch(req, res) {
+  const batch = await PaymentBatch.findByPk(req.params.batchId);
+  if (!batch) {
+    return res.status(404).json({
+      error: 'PAYMENT_BATCH_NOT_FOUND',
+      message: 'Payment batch not found'
+    });
+  }
+  res.json(batch);
+}
+
+module.exports = {
+  generatePayment,
+  downloadFile,
+  retryHrms,
+  getBatch
+};
