+import { useState } from 'react';
+import {
+  Alert,
+  Box,
+  Button,
+  CircularProgress,
+  Paper,
+  Stack,
+  TextField,
+  Typography
+} from '@mui/material';
+import { Download, PlayArrow, Sync } from '@mui/icons-material';
+import client from '../api/client';
+import PaymentStatusCard from '../components/PaymentStatusCard';
+
+function PaymentPage() {
+  const [payPeriodId, setPayPeriodId] = useState('1');
+  const [actor, setActor] = useState('Accounting Staff');
+  const [result, setResult] = useState(null);
+  const [message, setMessage] = useState('');
+  const [error, setError] = useState('');
+  const [loading, setLoading] = useState(false);
+
+  async function generatePayment() {
+    setLoading(true);
+    setError('');
+    setMessage('');
+    try {
+      const response = await client.post('/payments/generate', {
+        payPeriodId: Number(payPeriodId),
+        actor
+      });
+      setResult(response.data);
+      setMessage('Payment file generated and HRMS sync attempted.');
+    } catch (err) {
+      const data = err.response?.data;
+      setError(data?.message || 'Unable to generate payment file.');
+      setResult(data || null);
+    } finally {
+      setLoading(false);
+    }
+  }
+
+  async function retryHrms() {
+    if (!result?.paymentBatchId) {
+      return;
+    }
+
+    setLoading(true);
+    setError('');
+    setMessage('');
+    try {
+      const response = await client.post(`/payments/${result.paymentBatchId}/retry-hrms`, { actor });
+      setResult((current) => ({
+        ...current,
+        ...response.data,
+        hrmsSync: response.data.hrmsSync,
+        batchStatus: response.data.batchStatus
+      }));
+      setMessage('HRMS sync completed.');
+    } catch (err) {
+      setError(err.response?.data?.message || 'Unable to retry HRMS sync.');
+    } finally {
+      setLoading(false);
+    }
+  }
+
+  function downloadFile() {
+    if (!result?.paymentBatchId) {
+      return;
+    }
+    window.open(`${client.defaults.baseURL}/payments/${result.paymentBatchId}/file`, '_blank');
+  }
+
+  const missingStaff = result?.affectedStaff || [];
+
+  return (
+    <Stack spacing={3}>
+      <Box>
+        <Typography variant="h4" sx={{ mb: 1 }}>
+          Payment File & HRMS Sync
+        </Typography>
+        <Typography color="text.secondary">
+          Member 5 workflow for approved payroll periods.
+        </Typography>
+      </Box>
+
+      <Paper variant="outlined" sx={{ p: 3 }}>
+        <Stack spacing={2}>
+          <Stack direction={{ xs: 'column', md: 'row' }} spacing={2}>
+            <TextField
+              label="Pay Period ID"
+              value={payPeriodId}
+              onChange={(event) => setPayPeriodId(event.target.value)}
+              type="number"
+              fullWidth
+            />
+            <TextField
+              label="Actor"
+              value={actor}
+              onChange={(event) => setActor(event.target.value)}
+              fullWidth
+            />
+          </Stack>
+
+          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
+            <Button
+              variant="contained"
+              startIcon={loading ? <CircularProgress size={16} color="inherit" /> : <PlayArrow />}
+              onClick={generatePayment}
+              disabled={loading}
+            >
+              Generate Payment File
+            </Button>
+            <Button
+              variant="outlined"
+              startIcon={<Download />}
+              onClick={downloadFile}
+              disabled={!result?.paymentBatchId}
+            >
+              Download File
+            </Button>
+            <Button
+              variant="outlined"
+              startIcon={<Sync />}
+              onClick={retryHrms}
+              disabled={!result?.paymentBatchId || loading}
+            >
+              Retry HRMS
+            </Button>
+          </Stack>
+        </Stack>
+      </Paper>
+
+      {message && <Alert severity="success">{message}</Alert>}
+      {error && <Alert severity="error">{error}</Alert>}
+
+      {missingStaff.length > 0 && (
+        <Alert severity="warning">
+          Missing bank details: {missingStaff.map((staff) => staff.fullName).join(', ')}
+        </Alert>
+      )}
+
+      <PaymentStatusCard result={result} />
+    </Stack>
+  );
+}
