+import { Card, CardContent, Chip, Divider, Stack, Typography } from '@mui/material';
+
+function statusColor(status) {
+  if (status === 'completed' || status === 'payment_ready') {
+    return 'success';
+  }
+  if (status === 'hrms_sync_failed' || status === 'failed') {
+    return 'error';
+  }
+  return 'warning';
+}
+
+function PaymentStatusCard({ result }) {
+  if (!result) {
+    return null;
+  }
+
+  return (
+    <Card variant="outlined">
+      <CardContent>
+        <Stack spacing={2}>
+          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }}>
+            <Typography variant="h6">Payment Batch #{result.paymentBatchId}</Typography>
+            <Chip label={result.batchStatus || result.status} color={statusColor(result.batchStatus || result.status)} />
+            <Chip label={`HRMS: ${result.hrmsSync}`} color={statusColor(result.hrmsSync)} variant="outlined" />
+          </Stack>
+          <Divider />
+          <Stack direction={{ xs: 'column', md: 'row' }} spacing={3}>
+            <Typography>Pay Period: {result.payPeriodId}</Typography>
+            <Typography>File Format: {result.fileFormat}</Typography>
+            <Typography>Payslips: {result.payslipsGenerated}</Typography>
+          </Stack>
+          {result.fileUrl && (
+            <Typography>
+              Download path: <strong>{result.fileUrl}</strong>
+            </Typography>
+          )}
+        </Stack>
+      </CardContent>
+    </Card>
+  );
+}
+
+export default PaymentStatusCard;

