+        bankCode: 'OCBC',
+        bankAccountNo: '987654321'
+      }
+    }
+  ];
+
+  const file = formatGiroFile({
+    payPeriod,
+    lines,
+    generatedAt: new Date('2026-06-16T02:00:00.000Z')
+  });
+
