    color: #fff;
    display: flex;
    align-items: baseline;
    gap: .75rem;
  }
  .section-header .sec-label {
    font-family: 'DM Mono', monospace;
    font-size: .68rem;
    letter-spacing: .12em;
    opacity: .7;
  }
  .section-header h2 { font-family: 'DM Serif Display', serif; font-size: 1.2rem; }

  .sec-db       .section-header { background: var(--db); }
  .sec-storage  .section-header { background: var(--storage); }
  .sec-backend  .section-header { background: var(--backend); }
  .sec-frontend .section-header { background: var(--frontend); }

  .section-body {
    background: #fff;
    border: 1px solid var(--rule);
    border-top: none;
    border-radius: 0 0 var(--radius) var(--radius);
    padding: 1.4rem 1.6rem;
    box-shadow: var(--shadow);
  }

  /* â”€â”€ Service cards â”€â”€ */
  .service-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 1rem;
    margin-bottom: 1.2rem;
  }
  .service-card {
    border: 1px solid var(--rule);
    border-radius: var(--radius);
    overflow: hidden;
  }
  .service-card-header {
    padding: .65rem 1rem;
    display: flex;
    align-items: center;
    gap: .6rem;
  }
  .service-card-header .svc-name {
    font-weight: 700;
    font-size: .95rem;
  }
  .service-card-header .svc-tag {
    margin-left: auto;
    font-family: 'DM Mono', monospace;
    font-size: .65rem;
    font-weight: 600;
    padding: .15rem .5rem;
    border-radius: 999px;
    background: rgba(255,255,255,.35);
  }
  .service-card-body {
    padding: .85rem 1rem;
    font-size: .85rem;
    color: var(--ink-soft);
  }
  .service-card-body p { margin-bottom: .5rem; color: var(--ink-soft); font-size: .85rem; }
  .service-card-body p:last-child { margin-bottom: 0; }
  .service-card-body strong { color: var(--ink); }

  /* Card accent colours by section */
  .sec-db       .service-card-header { background: var(--db-bg);       color: var(--db); }
  .sec-storage  .service-card-header { background: var(--storage-bg);  color: var(--storage); }
  .sec-backend  .service-card-header { background: var(--backend-bg);  color: var(--backend); }
  .sec-frontend .service-card-header { background: var(--frontend-bg); color: var(--frontend); }

  /* â”€â”€ Steps â”€â”€ */
  .steps { list-style: none; padding: 0; margin-top: .4rem; }
  .steps li {
    display: flex;
    gap: .85rem;
    padding: .55rem 0;
    border-bottom: 1px solid var(--rule);
    font-size: .88rem;
    align-items: flex-start;
  }
  .steps li:last-child { border-bottom: none; }
  .step-num {
    flex-shrink: 0;
    width: 22px; height: 22px;
    border-radius: 50%;
    font-family: 'DM Mono', monospace;
    font-size: .72rem;
    font-weight: 700;
    display: flex; align-items: center; justify-content: center;
    margin-top: .1rem;
  }
  .sec-db       .step-num { background: var(--db-bg);       color: var(--db); }
  .sec-storage  .step-num { background: var(--storage-bg);  color: var(--storage); }
  .sec-backend  .step-num { background: var(--backend-bg);  color: var(--backend); }
  .sec-frontend .step-num { background: var(--frontend-bg); color: var(--frontend); }

  .step-body { flex: 1; line-height: 1.5; color: var(--ink); }
  .step-body .step-title { font-weight: 600; display: block; margin-bottom: .1rem; }
  .step-body p { font-size: .84rem; color: var(--ink-soft); margin: .15rem 0 0; }

  /* â”€â”€ Code blocks â”€â”€ */
  .code-block {
    background: var(--mono-bg);
    border-radius: 8px;
    padding: .9rem 1.1rem;
    margin: .8rem 0;
    overflow-x: auto;
    font-family: 'DM Mono', monospace;
    font-size: .8rem;
    line-height: 1.8;
  }
  .code-block .comment { color: var(--mono-comment); }
  .code-block .key     { color: var(--mono-key); }
  .code-block .val     { color: var(--mono-val); }
  .code-block .str     { color: var(--mono-str); }
  .code-block .var     { color: var(--mono-var); }
  .code-block .plain   { color: var(--mono-text); }

  code {
    font-family: 'DM Mono', monospace;
    font-size: .82em;
    background: #f0f0f0;
    padding: .1em .35em;
    border-radius: 4px;
    color: var(--ink);
  }

  /* â”€â”€ Notice â”€â”€ */
  .notice {
    border-radius: var(--radius);
    padding: .9rem 1.1rem;
    margin: 1rem 0;
    font-size: .86rem;
    display: flex;
    gap: .7rem;
    align-items: flex-start;
  }
  .notice .icon { flex-shrink: 0; margin-top: .05rem; }
  .notice.warn  { background: #fff8e1; border-left: 4px solid #f59e0b; color: #5a3e00; }
  .notice.tip   { background: #eaf7f0; border-left: 4px solid var(--storage); color: #0a3320; }
  .notice.info  { background: var(--db-bg); border-left: 4px solid var(--db); color: #0a1f40; }

  h3 {
    font-family: 'DM Serif Display', serif;
    font-size: 1rem;
    color: var(--ink);
    margin: 1.3rem 0 .6rem;
  }
  h3:first-child { margin-top: 0; }

  .divider { border: none; border-top: 1px solid var(--rule); margin: 1.4rem 0; }

  /* â”€â”€ Env table â”€â”€ */
  .env-table { width: 100%; border-collapse: collapse; font-size: .84rem; margin-top: .6rem; }
  .env-table th {
    text-align: left;
    padding: .45rem .7rem;
    background: var(--mono-bg);
    color: var(--mono-text);
    font-family: 'DM Mono', monospace;
    font-size: .72rem;
    letter-spacing: .06em;
  }
  .env-table td {
    padding: .45rem .7rem;
    border-bottom: 1px solid var(--rule);
    vertical-align: top;
  }
  .env-table tr:last-child td { border-bottom: none; }
  .env-table .ekey  { font-family: 'DM Mono', monospace; font-size: .78rem; color: var(--mono-key); }
  .env-table .edesc { color: var(--ink-soft); }
</style>
</head><body><div class="page"><!-- Header --><header class="doc-header">
<h1>Full Stack Application Development</h1>
<p>App Deployment Guide &nbsp;Â·&nbsp; Cloud Services for Students</p>
</header><!-- Architecture overview -->
<div class="arch-strip">
<div class="arch-box frontend"><span class="label">FRONTEND</span>Vercel</div>
<div class="arch-arrow">â†’</div>
<div class="arch-box backend"><span class="label">BACKEND</span>Render</div>
<div class="arch-arrow">â†’</div>
<div class="arch-box db"><span class="label">DATABASE</span>Neon / Supabase / MongoDB</div>
<div class="arch-arrow">â†’</div>
<div class="arch-box storage"><span class="label">STORAGE</span>Drive / Cloudinary / YouTube</div>
</div>
<!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• --><!-- DATABASE --><!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• -->
<section class="section sec-db">
<div class="section-header"><span class="sec-label">STEP 1</span>
<h2>Database</h2>
</div>
<div class="section-body">
<p style="color: var(--ink-soft); font-size: .88rem; margin-bottom: 1rem;">Choose <strong>one</strong> database service for your project. Pick based on your data structure and whether you need built-in authentication.</p>
<div class="service-grid"><!-- Neon -->
<div class="service-card">
<div class="service-card-header"><span class="svc-name">Neon Postgres</span> <span class="svc-tag">SQL</span></div>
<div class="service-card-body">
<p><strong>Best for:</strong> Relational data with structured schemas.</p>
<p><strong>Free tier:</strong> 512 MB storage, 1 project.</p>
<p><strong>Connection:</strong> Standard PostgreSQL connection string.</p>
</div>
</div>
<!-- Supabase -->
<div class="service-card">
<div class="service-card-header"><span class="svc-name">Supabase</span> <span class="svc-tag">SQL + Auth</span></div>
<div class="service-card-body">
<p><strong>Best for:</strong> Relational data <em>and</em> built-in user authentication.</p>
<p><strong>Free tier:</strong> 500 MB storage, 2 projects.</p>
<p><strong>Connection:</strong> Postgres connection string + Supabase client SDK.</p>
</div>
</div>
<!-- MongoDB -->
<div class="service-card">
<div class="service-card-header"><span class="svc-name">MongoDB Atlas</span> <span class="svc-tag">NoSQL</span></div>
<div class="service-card-body">
<p><strong>Best for:</strong> Flexible, document-based data (JSON-like).</p>
<p><strong>Free tier:</strong> 512 MB shared cluster (M0).</p>
<p><strong>Connection:</strong> MongoDB connection string via Mongoose.</p>
</div>
</div>
</div>
<h3>Setup Steps</h3>
<ol class="steps">
<li>
<div class="step-num">1</div>
<div class="step-body"><span class="step-title">Create an account and a new project</span>
<p>Sign up at <a href="https://neon.tech" target="_blank" rel="noopener">neon.tech</a>, <a href="https://supabase.com" target="_blank" rel="noopener">supabase.com</a>, or <a href="https://www.mongodb.com/cloud/atlas" target="_blank" rel="noopener">mongodb.com/cloud/atlas</a>. Create a new project and a database.</p>
</div>
</li>
<li>
<div class="step-num">2</div>
<div class="step-body"><span class="step-title">Copy the connection string</span>
<p>Find the connection string in your dashboard. It will look like <code>postgresql://user:pass@host/db</code> or <code>mongodb+srv://user:pass@cluster.mongodb.net/db</code>.</p>
</div>
</li>
<li>
<div class="step-num">3</div>
<div class="step-body"><span class="step-title">Store it as an environment variable</span>
<p>Add it to your backend <code>.env</code> file as <code>DATABASE_URL</code>. Never commit this file. Add it to Render's environment variables when deploying.</p>
</div>
</li>
<li>
<div class="step-num">4</div>
<div class="step-body"><span class="step-title">Allow external connections (MongoDB only)</span>
<p>In MongoDB Atlas, go to <strong>Network Access</strong> and add <code>0.0.0.0/0</code> to allow connections from Render's IP range.</p>
</div>
</li>
</ol>
<div class="code-block"><span class="comment"># .env (backend) â€” never commit this file</span><br><span class="key">DATABASE_URL</span><span class="plain">=</span><span class="str">postgresql://user:password@host/dbname</span><span class="comment"> # Neon or Supabase</span><br><span class="comment"># OR</span><br><span class="key">DATABASE_URL</span><span class="plain">=</span><span class="str">mongodb+srv://user:password@cluster.mongodb.net/dbname</span><span class="comment"> # MongoDB</span></div>
<div class="notice warn"><span class="icon">âš ï¸</span> <span>Never commit your <code>.env</code> file. Add <code>.env</code> to your <code>.gitignore</code> and use <code>.env.example</code> with placeholder values instead.</span></div>
</div>
</section>
<!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• --><!-- FILE STORAGE --><!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• -->
<section class="section sec-storage">
<div class="section-header"><span class="sec-label">STEP 2</span>
<h2>File Storage <span style="font-family: 'DM Sans',sans-serif; font-size: .85rem; opacity: .75; font-weight: 300;">(if required)</span></h2>
</div>
<div class="section-body">
<p style="color: var(--ink-soft); font-size: .88rem; margin-bottom: 1rem;">Choose a storage service based on the type of files your app handles. You may use more than one.</p>
<div class="service-grid"><!-- Google Drive -->
<div class="service-card">
<div class="service-card-header"><span class="svc-name">Google Drive</span> <span class="svc-tag">Documents</span></div>
<div class="service-card-body">
<p><strong>Best for:</strong> PDFs, Word docs, spreadsheets, and general files.</p>
<p><strong>Free tier:</strong> 15 GB per Google account.</p>
<p><strong>Integration:</strong> Google Drive API or shareable public links.</p>
</div>
</div>
<!-- Cloudinary -->
<div class="service-card">
<div class="service-card-header"><span class="svc-name">Cloudinary</span> <span class="svc-tag">Images</span></div>
<div class="service-card-body">
<p><strong>Best for:</strong> Uploading, storing, and transforming images.</p>
<p><strong>Free tier:</strong> 25 credits/month (~25,000 transformations).</p>
<p><strong>Integration:</strong> Cloudinary SDK; returns a hosted URL after upload.</p>
</div>
</div>
<!-- YouTube -->
<div class="service-card">
<div class="service-card-header"><span class="svc-name">YouTube</span> <span class="svc-tag">Videos</span></div>
<div class="service-card-body">
<p><strong>Best for:</strong> Hosting and embedding video content.</p>
<p><strong>Free tier:</strong> Unlimited uploads (standard YouTube account).</p>
<p><strong>Integration:</strong> YouTube Data API or embed via video ID.</p>
</div>
</div>
</div>
<h3>Cloudinary Setup (recommended for images)</h3>
<ol class="steps">
<li>
<div class="step-num">1</div>
<div class="step-body"><span class="step-title">Create a free account</span>
<p>Sign up at <a href="https://cloudinary.com" target="_blank" rel="noopener">cloudinary.com</a> and note your <strong>Cloud Name</strong>, <strong>API Key</strong>, and <strong>API Secret</strong> from the dashboard.</p>
</div>
</li>
<li>
<div class="step-num">2</div>
<div class="step-body"><span class="step-title">Install the SDK in your backend</span>
<p>Run <code>npm install cloudinary multer</code>. Use <code>multer</code> to handle file uploads and Cloudinary to store them.</p>
</div>
</li>
<li>
<div class="step-num">3</div>
<div class="step-body"><span class="step-title">Add credentials to your environment</span>
<p>Store your Cloudinary credentials in <code>.env</code> and add them to Render's environment variables.</p>
</div>
</li>
<li>
<div class="step-num">4</div>
<div class="step-body"><span class="step-title">Save the returned URL to your database</span>
<p>After upload, Cloudinary returns a hosted URL. Save this URL to your database â€” don't store the file itself in the DB.</p>
</div>
</li>
</ol>
<div class="code-block"><span class="comment"># .env (backend)</span><br><span class="key">CLOUDINARY_CLOUD_NAME</span><span class="plain">=</span><span class="str">your-cloud-name</span><br><span class="key">CLOUDINARY_API_KEY</span><span class="plain">=</span><span class="str">your-api-key</span><br><span class="key">CLOUDINARY_API_SECRET</span><span class="plain">=</span><span class="str">your-api-secret</span></div>
</div>
</section>
<!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• --><!-- BACKEND â€” RENDER --><!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• -->
<section class="section sec-backend">
<div class="section-header"><span class="sec-label">STEP 3</span>
<h2>Node.js Backend â€” Render</h2>
</div>
<div class="section-body">
<div class="notice info"><span class="icon">â„¹ï¸</span> <span>Deploy your backend <strong>before</strong> your frontend. You'll need the backend's live URL to configure the frontend's API base URL.</span></div>
<h3>Setup Steps</h3>
<ol class="steps">
<li>
<div class="step-num">1</div>
<div class="step-body"><span class="step-title">Create a free account</span>
<p>Sign up at <a href="https://render.com" target="_blank" rel="noopener">render.com</a> and connect your GitHub account.</p>
</div>
</li>
<li>
<div class="step-num">2</div>
<div class="step-body"><span class="step-title">Create a new Web Service</span>
<p>Click <strong>New â†’ Web Service</strong>, select your repository, and choose the <code>backend/</code> folder as the root directory.</p>
</div>
</li>
<li>
<div class="step-num">3</div>
<div class="step-body"><span class="step-title">Configure build and start commands</span>
<p>Set <strong>Build Command</strong> to <code>npm install</code> and <strong>Start Command</strong> to <code>node src/index.js</code> (or your entry point).</p>
</div>
</li>
<li>
<div class="step-num">4</div>
<div class="step-body"><span class="step-title">Add environment variables</span>
<p>Go to <strong>Environment</strong> and add all your <code>.env</code> variables â€” <code>DATABASE_URL</code>, <code>JWT_SECRET</code>, Cloudinary keys, and any others.</p>
</div>
</li>
<li>
<div class="step-num">5</div>
<div class="step-body"><span class="step-title">Deploy and copy the live URL</span>
<p>Click <strong>Deploy</strong>. Once live, copy your service URL (e.g. <code>https://your-app.onrender.com</code>). You'll need this for the frontend.</p>
</div>
</li>
<li>
<div class="step-num">6</div>
<div class="step-body"><span class="step-title">Configure CORS</span>
<p>Update your Express CORS config to allow your Vercel frontend URL. Without this, your frontend will get blocked by the browser.</p>
</div>
</li>
</ol>
<div class="code-block"><span class="comment">// backend/src/index.js â€” CORS setup</span><br><span class="var">app</span><span class="plain">.use(cors({</span><br><span class="plain"> </span><span class="key">origin</span><span class="plain">: </span><span class="str">process.env.FRONTEND_URL</span><span class="plain">,</span><br><span class="plain"> </span><span class="key">credentials</span><span class="plain">: </span><span class="val">true</span><br><span class="plain">}));</span></div>
<div class="code-block"><span class="comment"># Render environment variables</span><br><span class="key">DATABASE_URL</span><span class="plain"> = </span><span class="str">your-database-connection-string</span><br><span class="key">JWT_SECRET</span><span class="plain"> = </span><span class="str">your-secret-key</span><br><span class="key">FRONTEND_URL</span><span class="plain"> = </span><span class="str">https://your-app.vercel.app</span><br><span class="key">NODE_ENV</span><span class="plain"> = </span><span class="str">production</span></div>
<div class="notice warn"><span class="icon">âš ï¸</span> <span>Render free tier services <strong>spin down after 15 minutes of inactivity</strong> and take ~30 seconds to wake up on the next request. This is expected â€” inform your tutor or client before the demo.</span></div>
</div>
</section>
<!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• --><!-- FRONTEND â€” VERCEL --><!-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• -->
<section class="section sec-frontend">
<div class="section-header"><span class="sec-label">STEP 4</span>
<h2>React.js Frontend â€” Vercel</h2>
</div>
<div class="section-body">
<h3>Setup Steps</h3>
<ol class="steps">
<li>
<div class="step-num">1</div>
<div class="step-body"><span class="step-title">Create a free account</span>
<p>Sign up at <a href="https://vercel.com" target="_blank" rel="noopener">vercel.com</a> and connect your GitHub account.</p>
</div>
</li>
<li>
<div class="step-num">2</div>
<div class="step-body"><span class="step-title">Import your repository</span>
<p>Click <strong>New Project â†’ Import Git Repository</strong>. Select your repo and set the <strong>Root Directory</strong> to <code>frontend/</code>.</p>
</div>
</li>
<li>
<div class="step-num">3</div>
<div class="step-body"><span class="step-title">Set framework preset</span>
<p>Vercel should auto-detect <strong>Create React App</strong> or <strong>Vite</strong>. Confirm the framework preset is correct before deploying.</p>
</div>
</li>
<li>
<div class="step-num">4</div>
<div class="step-body"><span class="step-title">Add environment variables</span>
<p>Add <code>VITE_API_URL</code> (or <code>REACT_APP_API_URL</code>) pointing to your Render backend URL. All frontend env variables must be prefixed with <code>VITE_</code> (Vite) or <code>REACT_APP_</code> (CRA) to be accessible in the browser.</p>
</div>
</li>
<li>
<div class="step-num">5</div>
<div class="step-body"><span class="step-title">Deploy</span>
<p>Click <strong>Deploy</strong>. Vercel will build and publish your frontend. Future pushes to your main branch will automatically redeploy.</p>
</div>
</li>
<li>
