payload.message:
Sure. Make these **3 small changes**.

**1. Backend Database Config**
File:

```text
payroll-automation/backend/src/config/database.js
```

Replace the whole file with:

```js
require('dotenv').config();

const config = {
  dialect: 'postgres',
  logging: process.env.DB_LOGGING === 'true' ? console.log : false,
  timezone: '+08:00'
};

if (process.env.DATABASE_URL) {
  config.url = process.env.DATABASE_URL;
  config.dialectOptions = {
    ssl: process.env.NODE_ENV === 'production'
      ? { require: true, rejectUnauthorized: false }
      : false
  };
} else {
  config.database = process.env.DB_NAME || 'payroll_automation';
  config.username = process.env.DB_USER || 'postgres';
  config.password = process.env.DB_PASSWORD || process.env.DB_PWD || 'postgres';
  config.host = process.env.DB_HOST || 'localhost';
  config.port = Number(process.env.DB_PORT || 5432);
}

module.exports = config;
```

Then update this file:

```text
payroll-automation/backend/src/models/index.js
```

Find this part:

```js
const sequelize = new Sequelize(
  databaseConfig.database,
  databaseConfig.username,
  databaseConfig.password,
  {
    host: databaseConfig.host,
    port: databaseConfig.port,
    dialect: databaseConfig.dialect,
    logging: databaseConfig.logging,
    timezone: databaseConfig.timezone
  }
);
```

Replace it with:

```js
const sequelize = databaseConfig.url
  ? new Sequelize(databaseConfig.url, {
      dialect: databaseConfig.dialect,
      logging: databaseConfig.logging,
      timezone: databaseConfig.timezone,
      dialectOptions: databaseConfig.dialectOptions
    })
  : new Sequelize(
      databaseConfig.database,
      databaseConfig.username,
      databaseConfig.password,
      {
        host: databaseConfig.host,
        port: databaseConfig.port,
        dialect: databaseConfig.dialect,
        logging: databaseConfig.logging,
        timezone: databaseConfig.timezone
      }
    );
```

**2. Backend CORS**
File:

```text
payroll-automation/backend/src/app.js
```

Find:

```js
app.use(cors({
  origin: process.env.CLIENT_URL || '*'
}));
```

Replace with:

```js
app.use(cors({
  origin: process.env.FRONTEND_URL || process.env.CLIENT_URL || '*',
  credentials: true
}));
```

**3. Frontend API URL**
File:

```text
payroll-automation/frontend/src/api/client.js
```

Replace the whole file with:

```js
import axios from 'axios';

const apiUrl =
  import.meta.env.VITE_API_URL ||
  import.meta.env.VITE_API_BASE_URL ||
  'http://localhost:3001/api';

const client = axios.create({
  baseURL: apiUrl
});

export default client;
```

**Environment Variables For Deployment**

For Render backend, use:

```env
DATABASE_URL=your_neon_or_supabase_postgres_url
FRONTEND_URL=https://your-vercel-app.vercel.app
NODE_ENV=production
APP_PORT=3001
HRMS_FORCE_FAIL=false
```

For Vercel frontend, use:

```env
VITE_API_URL=https://your-render-backend.onrender.com/api
```

That’s all you need to align with the deployment guide.

